window.ScripturaLexicons.BDAG_PART_0274 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-01\" data-source=\"BDAG\" data-search=\"παρειστήκειν remissão verbal ver παρίστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρειστήκειν</td><td>remissão verbal</td><td>ver παρίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-02\" data-source=\"BDAG\" data-search=\"παρεισφέρω verbo empregar; aplicar todos os esforços BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεισφέρω</td><td>verbo</td><td>empregar; aplicar todos os esforços</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-03\" data-source=\"BDAG\" data-search=\"παρεκβαίνω verbo transgredir; ultrapassar limites BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεκβαίνω</td><td>verbo</td><td>transgredir; ultrapassar limites</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-04\" data-source=\"BDAG\" data-search=\"παρέκβασις, εως, ἡ substantivo feminino desvio de um curso prescrito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρέκβασις, εως, ἡ</td><td>substantivo feminino</td><td>desvio de um curso prescrito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-05\" data-source=\"BDAG\" data-search=\"παρεκδέχομαι verbo interpretar erroneamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεκδέχομαι</td><td>verbo</td><td>interpretar erroneamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-06\" data-source=\"BDAG\" data-search=\"παρεκτός advérbio e preposição além de; fora; exceto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεκτός</td><td>advérbio e preposição</td><td>além de; fora; exceto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-07\" data-source=\"BDAG\" data-search=\"παρεκφέρω verbo levar a algum lugar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεκφέρω</td><td>verbo</td><td>levar a algum lugar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-08\" data-source=\"BDAG\" data-search=\"παρεμβάλλω verbo cercar; interpor; insinuar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεμβάλλω</td><td>verbo</td><td>cercar; interpor; insinuar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-09\" data-source=\"BDAG\" data-search=\"παρεμβολή, ῆς, ἡ substantivo feminino acampamento; quartel; linha de batalha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεμβολή, ῆς, ἡ</td><td>substantivo feminino</td><td>acampamento; quartel; linha de batalha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-10\" data-source=\"BDAG\" data-search=\"παρεμπλέκω verbo misturar; entrelaçar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεμπλέκω</td><td>verbo</td><td>misturar; entrelaçar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-11\" data-source=\"BDAG\" data-search=\"παρέμπτωσις, εως, ἡ substantivo feminino inserção insidiosa; intriga BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρέμπτωσις, εως, ἡ</td><td>substantivo feminino</td><td>inserção insidiosa; intriga</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-12\" data-source=\"BDAG\" data-search=\"παρεμφέρω verbo introduzir; trazer para dentro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεμφέρω</td><td>verbo</td><td>introduzir; trazer para dentro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-13\" data-source=\"BDAG\" data-search=\"παρένεγκε remissão verbal ver παραφέρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρένεγκε</td><td>remissão verbal</td><td>ver παραφέρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-14\" data-source=\"BDAG\" data-search=\"παρενθυμέομαι verbo médio depoente desconsiderar; negligenciar; esquecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρενθυμέομαι</td><td>verbo médio depoente</td><td>desconsiderar; negligenciar; esquecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-15\" data-source=\"BDAG\" data-search=\"παρενοχλέω verbo incomodar; causar dificuldade desnecessária BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρενοχλέω</td><td>verbo</td><td>incomodar; causar dificuldade desnecessária</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-16\" data-source=\"BDAG\" data-search=\"παρεπιδημέω verbo hospedar-se temporariamente; visitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεπιδημέω</td><td>verbo</td><td>hospedar-se temporariamente; visitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-17\" data-source=\"BDAG\" data-search=\"παρεπίδημος, ον adjetivo substantivado residente temporário; estrangeiro; peregrino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρεπίδημος, ον</td><td>adjetivo substantivado</td><td>residente temporário; estrangeiro; peregrino</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-18\" data-source=\"BDAG\" data-search=\"παρέρχομαι verbo médio depoente passar; desaparecer; transgredir; atravessar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρέρχομαι</td><td>verbo médio depoente</td><td>passar; desaparecer; transgredir; atravessar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-19\" data-source=\"BDAG\" data-search=\"πάρεσις, εως, ἡ substantivo feminino deixar passar; não punir; tolerância provisória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάρεσις, εως, ἡ</td><td>substantivo feminino</td><td>deixar passar; não punir; tolerância provisória</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0274-20\" data-source=\"BDAG\" data-search=\"παρέχω verbo oferecer; proporcionar; causar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρέχω</td><td>verbo</td><td>oferecer; proporcionar; causar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0274-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρειστήκειν</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρειστήκειν</span>: veja <span class=\"greek\">παρίστημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεισφέρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεισφέρω</span>, aoristo helenístico <span class=\"greek\">παρεισήνεγκα</span> (B-D-F §81, 2; Rob. 338) (Demosth. e outros; PTebt 38, 12; 14 [113 a.C.]), aplicar, empregar: <span class=\"greek\">σπουδὴν</span> <span class=\"greek\">πᾶσαν</span> «fazer todo esforço, empenhar-se ao máximo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:5</a> (<span class=\"greek\">σπουδὴν</span> [<span class=\"greek\">πᾶσαν</span>] <span class=\"greek\">εἰσφέρειν</span> é uma expressão formal na koiné, referente a benfeitores e outras pessoas dedicadas ao bem comum: Polyb 21, 29, 12; Diod S 1, 83, 8; SIG [índice s.v. <span class=\"greek\">σπουδή</span>]; Jos., Ant. 20, 204).—M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεκβαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεκβαίνω</span> (Hes.+; OGI 573, 17), literalmente «ir além» ou «para fora» de um limite. Em nossa literatura, em sentido figurado: ultrapassar os limites da autoridade estabelecida, ir além, transgredir <span class=\"greek\">τὶ</span> «algo» (EpArist 112), ultrapassar <span class=\"greek\">τὸν</span> <span class=\"greek\">ὡρισμένον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λειτουργίας</span> <span class=\"greek\">κανόνα</span> «a norma estabelecida do ministério» 1 Cl 41:1. Acerca do mar, <span class=\"greek\">οὐ</span> <span class=\"greek\">παρεκβαίνει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">περιτεθειμένα</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">κλεῖθρα</span> «não ultrapassa os limites que lhe foram impostos» 20:6.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρέκβασις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρέκβασις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παρεκβαίνω</span>; Theophr., Aristot. e outros; Jos., C. Ap. 1, 57; 183, Vi. 367; Just., D. 32, 5 <span class=\"greek\">ἐν</span> <span class=\"greek\">παρεκβάσεσι</span> «em digressões»), desvio de um curso prescrito 1 Cl 20:3.—DELG s.v. <span class=\"greek\">βαίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεκδέχομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεκδέχομαι</span> (Polyb., M. Ant., Orig.), particípio do 1.º aoristo <span class=\"greek\">παρεκδεξάμενος</span>, interpretar erroneamente Papias (2:12).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεκτός</h1><div class=\"entry-meta\"><span>advérbio e preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεκτός</span>, advérbio (= <span class=\"greek\">παρέκ</span> Hom. e outros, de <span class=\"greek\">παρά</span>, <span class=\"greek\">ἐκ</span>).<br><br>① Relativo a ser diferente de algo e acrescentado a isso, com ênfase no caráter externo, além de, fora de, absolutamente: <span class=\"greek\">χωρὶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">π</span>. (subentendido <span class=\"greek\">γινομένων</span>) «à parte daquilo que deixo de mencionar» ou «daquilo que é externo» (isto é, sofrimentos etc.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:28</a>.<br><br>② Empregado como preposição com genitivo, relativo a algo deixado de fora de outras considerações, à parte de, exceto (Dositheus 45, 3 <span class=\"greek\">παρεκτὸς</span> <span class=\"greek\">ἐμοῦ</span>, latim praeter me; Cyrill. Scyth. p. 34, 4 <span class=\"greek\">π</span>. <span class=\"greek\">σαββάτου</span> = «exceto no sábado»; Geopon. 13, 15, 7; Etym. Magn. p. 652, 18; TestJob 30:5; TestZeb 1:4; Dt 1:36 Aq.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32</a>; 19:9, variante textual (AOtto, Die Eheschdg. im Mt ’39; KStaab, D. Unauflöslichkeit d. Ehe u. d. sog. ‘Ehebruchsklauseln’ b. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32</a> u. 19:9: EEichmann Festschr. ’40, 435–52, ZKT 67, ’43, 36–44; HBaltensweiler, D. Ehe im NT ’67, 59–102; GStrecker, ZNW 69, ’78, 52–56. Veja também <span class=\"greek\">πορνεία</span> 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:29</a>. <span class=\"greek\">π</span>. <span class=\"greek\">θεοῦ</span> «sem Deus, afastando de Deus» D 6:1.—DELG s.v. <span class=\"greek\">ἐξ</span>. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεκφέρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεκφέρω</span> (Plut., Mor. 102c; SIG 834, 18), levar a um lugar, <span class=\"greek\">λίθους</span> «pedras» Hs 9, 4, 8.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεμβάλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεμβάλλω</span>, futuro <span class=\"greek\">παρεμβαλῶ</span>; 2.º aoristo <span class=\"greek\">παρενέβαλον</span> LXX; particípio perfeito <span class=\"greek\">παρεμβεβληκώς</span> 1 Km 26:5; mais-que-perfeito, 3.ª pessoa do plural <span class=\"greek\">παρεμβεβλήκεισαν</span> Judg 7:12 A e 1 Km 13:16 (Aristoph., Demosth. e outros; papiros, LXX; Jos., C. Ap. 1, 229).<br><br>① Cercar um objeto ou área por todos os lados, pôr em torno, rodear. A palavra é empregada frequentemente (até na LXX) como termo técnico militar (cf. <span class=\"greek\">παρεμβολή</span>), mas com sentidos diversos, dependendo das táticas empregadas. <span class=\"greek\">παρεμβαλοῦσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐχθροί</span> <span class=\"greek\">σου</span> <span class=\"greek\">χάρακά</span> <span class=\"greek\">σοι</span> «teus inimigos levantarão uma paliçada contra ti» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:43</a> (variante textual <span class=\"greek\">περιβαλοῦσιν</span>; D apresenta <span class=\"greek\">βαλοῦσιν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σέ</span>). Cf. Is 29:3 <span class=\"greek\">βαλῶ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">χάρακα</span>; 37:33 <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κυκλώσῃ</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">χάρακα</span>. As interpretações diferem conforme se considere o texto uma profecia efetiva (modelada segundo passagens como as de Isaías acima citadas) ou uma profecia posterior ao acontecimento; neste último caso, poderia referir-se aos trabalhos de terraplenagem executados pelos soldados sob Tito (Jos., B. 5, 11, 4: 466).<br><br>② Colocar alguma coisa no meio, interpor, insinuar, figuradamente, acerca da ira: <span class=\"greek\">παρεμβάλλει</span> <span class=\"greek\">ἑαυτὴν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> «insinua-se no coração» Hm 5, 2, 2.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεμβολή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεμβολή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παρεμβάλλω</span>; Aeschin.+). Empregada sobretudo como termo técnico militar (Polyb. e outros; inscrições, papiros, LXX; En 1:4; TestSol 25:7; Test12Patr); assim, sempre em nossa literatura.<br><br>① Acampamento (fortificado) (Polyb. 3, 75, 5; 9; Diod S 13, 87, 2; 15, 84, 1 e outros; SIG 700, 20; POxy 736; LXX; Jos., Ant. 6, 110; 20, 152) <span class=\"greek\">ἡ</span> <span class=\"greek\">παρεμβολὴ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀλλοφύλων</span> «o acampamento dos estrangeiros» 1 Cl 55:4 (veja <span class=\"greek\">ἀλλόφυλος</span>). Sobre o acampamento israelita (LXX), <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρεμβολῆς</span> «fora do acampamento» (Ex 29:14. Cf. Lev 4:12, 21; 10:4f e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:11</a>; 1 Cl 4:11.—A <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:11</a> acrescenta-se, no v. 13, o apelo <span class=\"greek\">ἐξερχώμεθα</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>., dando-se como motivo que aqui não temos «cidade permanente». Nessa passagem, as palavras <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. parecem referir-se à separação das coisas mundanas em geral (cf. Philo, Gig. 54 <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρεμβολῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σωματικοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">στρατοπέδου</span> <span class=\"greek\">πήξας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">σκηνήν</span>); mas veja GBarton, JBL 57, ‘38, 204f, Roma.—HKoester, HTR 55, ’62, 299–315. Sobre Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:12</a>, variante textual (em lugar de <span class=\"greek\">πύλης</span>).—<span class=\"greek\">ἡ</span> <span class=\"greek\">παρεμβολὴ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> «o acampamento dos santos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:9</a> também deve ser entendido a partir do uso da palavra no AT.<br><br>② Quartel/instalação militar das tropas romanas em Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:34</a>, 37; 22:24; 23:10, 16, 32. Também sobre o quartel em Roma onde estavam alojados os soldados que acompanhavam Paulo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:16</a>, variante textual.<br><br>③ Um exército disposto em formação de combate, linha de batalha (Polyb.; Aelian, VH 14, 46; Ex 14:19f; Judg 4:16; 8:11; 1 Km 14:16; TestSol 25:7 <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Αἰγυπτίων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:34</a>.—FFensham, RevQ 4, ’63, 557–62.—DELG s.v. <span class=\"greek\">βάλλω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεμπλέκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεμπλέκω</span> (Diphilus, médico [III a.C.] em Athen. 2, 49, 57c; Hero Alex. I p. 20, 11; Oribasius, Ecl. 40: CMG VI 2, 2 p. 202, 7 <span class=\"greek\">π</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ποτῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τροφήν</span>; escólio sobre Pind., Eustath., Prooem. 9; PTurin 8, 28 [116 a.C.]), termo técnico médico: misturar, mesclar, combinar com, em sentido ampliado acerca dos falsos mestres: <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">παρεμπλέκουσιν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χριστόν</span> «misturam Jesus Cristo a si próprios (= aos seus ensinamentos)» ITr 6:2 (veja as variantes textuais no aparato de Bihlmeyer).—DELG s.v. <span class=\"greek\">πλέκω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρέμπτωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρέμπτωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">πτῶσις</span> e o perfeito de <span class=\"greek\">πίπτω</span>: <span class=\"greek\">πέπτωκα</span>; Aristot. e outros), lançamento de algo para dentro, além do que já há, trama insidiosa: <span class=\"greek\">διά</span> <span class=\"greek\">τινας</span> <span class=\"greek\">παρεμπτώσεις</span>, em um jogo de palavras, 1 Cl 51:1 (a palavra não se encontra na tradição manuscrita grega, mas Clemente de Alexandria a emprega em Strom. 4, 113, 1 numa paráfrase desta passagem, e as versões latina e copta de 1 Cl concordam com ele. Veja o aparato de Bihlmeyer).—DELG s.v. <span class=\"greek\">πίπτω</span> C.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεμφέρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεμφέρω</span> (Galen e Vett. Val. em diversos sentidos), trazer de uma posição para dentro, introduzir Hs 9, 4, 8.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρένεγκε</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρένεγκε</span>: veja <span class=\"greek\">παραφέρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρενθυμέομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρενθυμέομαι</span>, 1.º aoristo passivo <span class=\"greek\">παρενεθυμήθην</span> (M. Ant. 5, 5, 5; 6, 20, 2; Iambl., In Nicom. p. 83, 15 Pistelli; TAM II/1, 245, 13; POxf 3, 12 [142 d.C.]; Sb 7404, 39 [II d.C.]; Philo), considerar algum assunto indigno de atenção séria, desconsiderar, negligenciar, esquecer <span class=\"greek\">τὶ</span> «algo» (Philo, Spec. Leg. 4, 53), acerca de mandamentos, Hm 5, 2, 8 (<span class=\"greek\">τὴν</span> <span class=\"greek\">ἐντολὴν</span> <span class=\"greek\">ταύτην</span>); 12, 3, 6 (<span class=\"greek\">ταύτας</span>, isto é, <span class=\"greek\">ἐντολάς</span>). Referindo-se a um bom pensamento (<span class=\"greek\">τὸ</span> <span class=\"greek\">καλόν</span>), com <span class=\"greek\">αὐτό</span> subentendido, tratar como coisa de pouca importância Hs 5, 2, 7. Com referência aos pecados dos membros da família de Hermas, subentendendo-se <span class=\"greek\">αὐτάς</span>, v 2, 3, 1.—DELG s.v. <span class=\"greek\">θυμός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρενοχλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρενοχλέω</span>, futuro da 3.ª pessoa singular <span class=\"greek\">παρενοχλήσει</span> Job 16:3; 1.º aoristo <span class=\"greek\">παρενώχλησα</span> LXX. Passivo: futuro da 3.ª pessoa singular <span class=\"greek\">παρενοχληθήσεται</span> 2 Macc 11:31 (Hippocr. e outros; inscrições, papiros, LXX), causar incômodo desnecessário, causar dificuldade (a alguém), incomodar, importunar, com dativo de pessoa (Polyb. 1, 8, 1; Plut., Timol. 237 [3, 1]; Epict. 1, 9, 23; PGen 31, 4; LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:19</a>. Qualquer coisa que ultrapassasse as exigências indicadas no v. 20 constituiria uma imposição adicional (<span class=\"greek\">παρα</span>-).—New Docs 4, 166f. DELG s.v. <span class=\"greek\">ὄχλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεπιδημέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεπιδημέω</span>, particípio do 1.º aoristo <span class=\"greek\">παρεπιδημήσας</span> (veja o verbete seguinte; Polyb. 27, 6, 3; Diod S 1, 83, 8; 19, 61, 1; Aelian, VH 8, 7 p. 90, 29; inscrições frequentes; PPetr II, 13, 19 [258–253 a.C.]; UPZ 196 I, 13; 19 [119 a.C.]; EpArist 110; Philo, Conf. Lingu. 76, Agr. 65), permanecer por pouco tempo em lugar estranho, visitar, com <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> «junto a alguém» 1 Cl 1:2.—New Docs 4, 145. DELG s.v. <span class=\"greek\">δῆμος</span>. M-M. s.v. <span class=\"greek\">παρεπίδημος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρεπίδημος, ον</h1><div class=\"entry-meta\"><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρεπίδημος</span>, <span class=\"greek\">ον</span> (veja o verbete precedente; Polyb. 32, 6, 4; Athen. 5, 196a; OGI 383, 150; PPetr I, 19, 22 [225 a.C.]; III, 7, 15; LXX; Just., A I, 67, 6.—Dssm., B 146f [BS 149]), relativo a permanecer temporariamente em lugar estranho ou estrangeiro, estar de passagem, residir temporariamente; em nossa literatura, substantivado <span class=\"greek\">ὁ</span> <span class=\"greek\">παρεπίδημος</span> «estrangeiro, peregrino, residente temporário», acerca dos cristãos, que não têm neste mundo seu lar: <span class=\"greek\">ἐκλεκτοὶ</span> <span class=\"greek\">π</span>. «peregrinos escolhidos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:1</a>. (Com <span class=\"greek\">πάροικοι</span> [cf. Gen 23:4; Ps 38:13]) 2:11. (Com <span class=\"greek\">ξένοι</span>) <span class=\"greek\">π</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> «peregrinos sobre a terra» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:13</a> (cf. Ps.-Pla., Axioch. 365b <span class=\"greek\">παρεπιδημία</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βίος</span>.—MMeister, De Axiocho Dial., dissertação, Breslau 1915, 86ff). Os cognatos <span class=\"greek\">παρεπιδημέω</span> e <span class=\"greek\">παρεπιδημία</span> são usados em inscrições (veja índice de SIG, s.v.) em relação a funcionários civis que se distinguem por conduta exemplar no exercício de funções internacionais. De modo semelhante, o autor de 1 Pt estabelece íntima ligação entre a condição dos destinatários (como visitantes temporários no mundo devido à sua relação especial com Deus por meio de Jesus Cristo) e sua responsabilidade moral. Veja <span class=\"greek\">πάροικος</span> e a bibliografia ali citada.—DELG s.v. <span class=\"greek\">δῆμος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρέρχομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρέρχομαι</span>, médio depoente; futuro <span class=\"greek\">παρελεύσομαι</span>; 2.º aoristo <span class=\"greek\">παρῆλθον</span>, imperativo no grego helenístico <span class=\"greek\">παρελθάτω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:39</a> (também variante textual -<span class=\"greek\">ετω</span>; B-D-F §81, 3; Mlt-H. 209); perfeito <span class=\"greek\">παρελήλυθα</span> (Hom.+).<br><br>① Passar além de um ponto de referência, passar por, com acusativo de pessoa ou coisa (Aelian, VH 2, 35; Lucian, Merc. Cond. 15), um animal Hv 4, 1, 9; 4, 2, 1; um lugar Papias (3, 3). Acerca de Jesus e seus discípulos no lago: <span class=\"greek\">ἤθελεν</span> <span class=\"greek\">παρελθεῖν</span> <span class=\"greek\">αὐτούς</span> «queria passar por eles» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:48</a> (veja HWindisch, NThT 9, 1920, 298–308; GEysinga, ibid. 15, 1926, 221–29 e outros; Lohmeyer s.v. <span class=\"greek\">παράγω</span> 3; BvanIersel, em The Four Gospels, Festschrift Neirynck, ed. FvanSegbroeck e outros ’92, II 1065–76). <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span> <span class=\"greek\">ἐκείνης</span> «passar por aquela estrada» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:28</a> (construção com <span class=\"greek\">διά</span> como PAmh 154, 2; Num 20:17; Josh 24:17). <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λίμνην</span> GEb 34, 60. Absolutamente (X., An. 2, 4, 25) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:37</a>; 1 Cl 14:5 (Ps 36:36). Acerca de algo impessoal: passar despercebido, escapar à atenção (Theognis 419; Sir 42:20) Hs 8, 2, 5ab.<br><br>② Acerca do tempo: deixar de estar disponível para alguma coisa, passar (Soph., Hdt.+; inscrições, papiros, LXX; JosAs 29:8 cód. A; Tat. 26, 1 <span class=\"greek\">πῶς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">παρελθεῖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μέλλων</span>, <span class=\"greek\">εἰ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐνεστώς</span>;) <span class=\"greek\">ἡ</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">παρῆλθεν</span> «a hora já passou» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:15</a>. Acerca de determinado período (SSol 2:11 <span class=\"greek\">ὁ</span> <span class=\"greek\">χειμὼν</span> <span class=\"greek\">π</span>.; Jos., Ant. 15, 408) <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">νηστείαν</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">παρεληλυθέναι</span> «porque o jejum já havia terminado» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:9</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">παρεληλυθὼς</span> <span class=\"greek\">χρόνος</span> «o tempo passado» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:3</a> (cf. Isocr. 4, 167 <span class=\"greek\">χρόνος</span> … <span class=\"greek\">ἱκανὸς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παρεληλυθώς</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">τί</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δεινῶν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">γέγονεν</span>; PMagd 25, 3 <span class=\"greek\">παρεληλυθότος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χρόνου</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">παρεληλυθότα</span> (junto de <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐνεστῶτα</span> e <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλλοντα</span>; cf. Herm. Wr. 424, 10ff Sc.; Demosth. 4, 2; Jos., Ant. 10, 210) «as coisas passadas, o passado» (Demosth. 18, 191; Sir 42:19; Philo, Spec. Leg. 1, 334, Leg. All. 2, 42) B 1:7; B 5:3.—<span class=\"greek\">ἡ</span> <span class=\"greek\">γενεὰ</span> <span class=\"greek\">αὕτη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:34</a> pertence a esta acepção, se <span class=\"greek\">γ</span>. for entendido temporalmente.<br><br>③ Chegar ao fim e, portanto, deixar de existir, passar, desaparecer (Demosth. 18, 188 <span class=\"greek\">κίνδυνον</span> <span class=\"greek\">παρελθεῖν</span>; Theocr. 27, 8; Ps 89:6; Wsd 2:4; 5:9; Da 7:14 Theod.; TestJob 33:4 <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">ὅλος</span> <span class=\"greek\">παρελεύσεται</span>), acerca de pessoas: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἄνθος</span> <span class=\"greek\">χόρτου</span> <span class=\"greek\">παρελεύσεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:10</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18a</a>; 24:35a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:31a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:17</a>; 21:33a; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:1</a> t.r. <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">οὗτος</span> D 10:6 (cf. TestJob 33:4). <span class=\"greek\">ἡ</span> <span class=\"greek\">γενεὰ</span> <span class=\"greek\">αὕτη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:34</a> (mas veja 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:32</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">γενεαὶ</span> <span class=\"greek\">πᾶσαι</span> 1 Cl 50:3. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀργή</span> v. 4 (Is 26:20). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀρχαῖα</span> <span class=\"greek\">παρῆλθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:17</a>.—Passar no sentido de perder a força, tornar-se inválido (Ps 148:6; Esth 10:3b <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">τούτων</span>· <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">παρῆλθεν</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">λόγος</span>): <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">μου</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παρέλθωσιν</span> (ou <span class=\"greek\">οὐ</span> [<span class=\"greek\">μὴ</span>] <span class=\"greek\">παρελεύσονται</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:35b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:31b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:33b</a>. <span class=\"greek\">ἰῶτα</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μία</span> <span class=\"greek\">κεραία</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παρέλθῃ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18b</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παρέλθῃ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δεδογματισμένων</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span> 1 Cl 27:5.<br><br>④ Ignorar alguma coisa em favor de outras questões, passar por alto, transgredir, negligenciar, desobedecer <span class=\"greek\">τὶ</span> «algo» (Hes., Theog. 613; Lysias 6, 52 <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span>; Demosth. 37, 37; Dionys. Hal. 1, 58; Dt 17:2; Jer 41:18; Jdth 11:10; 1 Macc 2:22; ApcEsdr 5:17 <span class=\"greek\">τὴν</span> <span class=\"greek\">διαθήκην</span> <span class=\"greek\">μου</span>; Jos., Ant. 14, 67) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:42</a>; 15:29.<br><br>⑤ Passar ao largo sem tocar, passar, acerca de sofrimento ou adversidade (Jos., Ant. 5, 31, fogo), <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> «de alguém» (sobre a construção com <span class=\"greek\">ἀπό</span>, cf. 2 Ch 9:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:35</a>. Absolutamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:42</a>.<br><br>⑥ Atravessar uma área, passar por dentro (Appian, Bell. Civ. 5, 68 §288 <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀντώνιος</span> <span class=\"greek\">μόλις</span> <span class=\"greek\">παρῆλθεν</span> = «Antônio atravessou [até o Fórum] com dificuldade»; 1 Macc 5:48 <span class=\"greek\">διελεύσομαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">σου</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀπελθεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">ἡμῶν</span>· <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">κακοποιήσει</span> <span class=\"greek\">ὑμᾶς</span>, <span class=\"greek\">πλὴν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ποσὶν</span> <span class=\"greek\">παρελευσόμεθα</span>) <span class=\"greek\">παρελθόντες</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Μυσίαν</span> <span class=\"greek\">κατέβησαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Τρῳάδα</span> «atravessando a Mísia, desceram a Trôade» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:8</a> (a falta de conhecimento dessa acepção, juntamente com o reconhecimento de que «passar ao largo» seria impossível neste caso, deu origem à variante textual <span class=\"greek\">διελθόντες</span> D); cf. 17:15 D.<br><br>⑦ Fazer parada num lugar ao passar, vir a, passar por, vir para cá (trágicos, Hdt. e outros; inscrições, papiros, LXX, EpArist 176; Philo; Jos., Bell. 3, 347, Ant. 1, 337) <span class=\"greek\">παρελθὼν</span> <span class=\"greek\">διακονήσει</span> <span class=\"greek\">αὐτοῖς</span> «virá e lhes servirá» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:37</a>; «<span class=\"greek\">παρελθὼν</span> <span class=\"greek\">ἀνάπεσε</span>» = «vem cá, reclina-te» 17:7; acerca de Lísias, que veio com uma força considerável, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:6</a>[7], variante textual.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάρεσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάρεσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παρά</span> + <span class=\"greek\">ἵημι</span>; Hippocr.+; BGU 624, 21 [veja Dssm., NB 94=BS 266]; Philo; Jos., Ant. 11, 236; Ath., R. 16 p. 68, 4), desconsideração deliberada, deixar passar, deixar impune (Dionys. Hal. 7, 37 <span class=\"greek\">ὁλοσχερῆ</span> <span class=\"greek\">πάρεσιν</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὕροντο</span>, <span class=\"greek\">τὴν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">χρόνον</span> <span class=\"greek\">ἀναβολὴν</span> <span class=\"greek\">ἔλαβον</span>; Dio Chrys. 80 [30], 19 <span class=\"greek\">πάρεσίν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>.—O verbo correspondente <span class=\"greek\">παριέναι</span> significa «deixar impune»: X., Hipp. 7, 10; Dionys. Hal. 2, 35; Sir 23:2; Jos., Ant. 15, 48 <span class=\"greek\">παρῆκεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁμαρτίαν</span>.) <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">προγεγονότων</span> <span class=\"greek\">ἁμαρτημάτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:25</a>.—O verbo também é empregado para «remitir» dívidas e outras obrigações (Phalaris, Ep. 81, 1 <span class=\"greek\">χρημάτων</span>; SIG 742, 33; 39; OGI 669, 50.—JCreed, JTS 41, ’40, 28–30; SLyonnet, Biblica 38, ’57, 35–61), mas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:25</a> Paulo parece argumentar que o aparente ato de Deus de fechar os olhos ao pecado põe em risco a própria retidão divina (cf. tradução de WBeck, ’76, «pacientemente deixou passar»; NRSV, REB, com muitos estudiosos).—WKümmel, <span class=\"greek\">Πάρεσις</span> u. <span class=\"greek\">ἔνδειξις</span>: ZTK 49, ’52, 154–67. Veja s.v. <span class=\"greek\">ἔνδειξις</span> 2. JFitzmyer, comentário (Anchor), s.v.—DELG s.v. <span class=\"greek\">ἵημι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0274-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρέχω</span>, imperfeito <span class=\"greek\">παρεῖχον</span>, também 3.ª pessoa do plural <span class=\"greek\">παρεῖχαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:2</a>, variante textual (grego helenístico; veja B-D-F §82; Mlt-H. 194); futuro <span class=\"greek\">παρέξω</span>; 2.º aoristo <span class=\"greek\">παρέσχον</span>; perfeito <span class=\"greek\">παρέσχηκα</span>. Médio: imperfeito <span class=\"greek\">παρειχόμην</span>; futuro da 1.ª pessoa singular <span class=\"greek\">παρέξομαι</span> (ApcPt Rainer), da 2.ª singular <span class=\"greek\">παρέξῃ</span>, da 1.ª plural <span class=\"greek\">παρεξόμεθα</span> Esth 8:12h; imperativo do 2.º aoristo, 2.ª pessoa singular <span class=\"greek\">παράσχου</span> Ps 29:8, infinitivo <span class=\"greek\">παρασχέσθαι</span> 4 Macc 3:2. Passivo: subjuntivo aoristo da 3.ª pessoa singular <span class=\"greek\">παρασχεθῇ</span> (Just., A I, 68, 7) (Hom.+).<br><br>① Tornar disponível, entregar, oferecer, apresentar (escólio sobre Nicander, Alexiph. 204 <span class=\"greek\">παρέχειν</span> <span class=\"greek\">πίνειν</span> = «oferecer de beber»), <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> «algo a alguém», <span class=\"greek\">τὴν</span> <span class=\"greek\">σιαγόνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:29</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῦτος</span> Hs 2:7.<br><br>② Fazer alguém experimentar algo, conceder, manifestar.<br><br>ⓐ Ativo: conceder, demonstrar <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> «algo a alguém» (Vi. Aesopi G 124 P. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">παρεῖχον</span>; Aesop, Fab. 396 P.=170 H.; Jos., Ant. 2, 329; 11, 2) Dg 12:1. <span class=\"greek\">ἀγάπην</span> «amor» 1 Cl 21:7. <span class=\"greek\">φιλανθρωπίαν</span> «benevolência» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:2</a>. Acerca de Deus (Appian, Bell. Civ. 3, 65 §265 <span class=\"greek\">ἢν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">παρέχωσιν</span> <span class=\"greek\">εὐπραγεῖν</span>; Alex. Aphr., Quaest. 1, 14 Bruns) <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">πάντα</span> «tudo para nós» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:17</a>; cf. Dg 8:11. <span class=\"greek\">ὅσα</span> … <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">παρέσχεν</span> AcPl Ha 8, 16//Ox 1602, 18//BMM recto 20 (cf. Just., A I, 10, 1 <span class=\"greek\">θεὸν</span> … <span class=\"greek\">παρέχοντα</span> <span class=\"greek\">πάντα</span>), <span class=\"greek\">ὧν</span> (atração do relativo a partir de <span class=\"greek\">ἅ</span>) <span class=\"greek\">τοῖς</span> <span class=\"greek\">οἰομένοις</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">παρέχει</span> <span class=\"greek\">αὐτός</span> «aquilo que ele próprio proporciona àqueles que julgam estar dando» Dg 3:4. <span class=\"greek\">πίστιν</span> <span class=\"greek\">παρασχὼν</span> <span class=\"greek\">πᾶσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:31</a> (veja <span class=\"greek\">πίστις</span> 1c).—Sem dativo (Pind., Paeanes 4, 24 Sch.=OxfT 4, 21 <span class=\"greek\">μοῖσαν</span>; Just., D. 3, 6 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπιστήμην</span>) <span class=\"greek\">νοῦν</span> «conceder entendimento» Dg 11:5. <span class=\"greek\">ἡσυχίαν</span> «silêncio» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:2</a> (cf. Jos., Ant. 5, 235). <span class=\"greek\">δεῖγμά</span> <span class=\"greek\">τινος</span> Dg 3:3 (veja <span class=\"greek\">δεῖγμα</span> 2 e 1).—Sem o acusativo, subentendido pelo contexto, Dg 3:5; ISm 11:3.—Com dativo seguido de infinitivo MPol 18:2.<br><br>ⓑ Médio (B-D-F §316, 3; Rob. 810): <span class=\"greek\">ἑαυτόν</span> <span class=\"greek\">τι</span> «mostrar-se ser algo» (X., Cyr. 8, 1, 39; SIG 333, 10f [306 a.C.]; 442, 8f; 620, 5f; 748, 31f; 1068, 6f; 1104, 18f; UPZ 144, 15 [164/163 a.C.]; POxy 281, 13; CPR 27, 14.—Dssm., NB 81f [BS 254]; Thieme 24; Rouffiac 52. No grego mais antigo, por exemplo Antiphon, Pla. e outros, seria empregada a voz ativa, como também em Jos., C. Ap. 2, 156) <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">παρεχόμενος</span> <span class=\"greek\">τύπον</span> Tit 2:7.<br><br>③ Fazer algo acontecer ou ser provocado, causar, produzir.<br><br>ⓐ Ativo: causar, produzir <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> «algo para alguém» (Hdt. 1, 177 <span class=\"greek\">πόνον</span>; Socrat., Ep. 14, 1 <span class=\"greek\">κακά</span>; Arrian, Anab. 2, 21, 3 <span class=\"greek\">φόβον</span>; EpArist 96 <span class=\"greek\">ἔκπληξιν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">π</span>.; Jos., Ant. 18, 175 <span class=\"greek\">ὄχλον</span> [= «incômodo»] <span class=\"greek\">μοι</span> <span class=\"greek\">π</span>.; Just., A I, 4, 7 <span class=\"greek\">ἀφορμάς</span>, A II, 4, 1 <span class=\"greek\">πράγματα</span>) <span class=\"greek\">κόπους</span> «causar transtorno» (veja <span class=\"greek\">κόπος</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:7</a>; 18:5 (<span class=\"greek\">κόπον</span>, como Sir 29:4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:17</a>; AcPlCor 2:34 (<span class=\"greek\">κόπους</span> <span class=\"greek\">μοι</span> <span class=\"greek\">μηδεὶς</span> <span class=\"greek\">παρεχέτω</span>, relacionado a PGM 14b [<span class=\"greek\">ἐάν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δεῖνα</span> <span class=\"greek\">κόπους</span> <span class=\"greek\">παράσχῃ</span>], é considerado uma fórmula de adjuração por Dssm., B 262ff [BS 352–60], LO 256 [LAE 301]); Hv 3, 3, 2 (<span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> «acerca de alguma coisa»). <span class=\"greek\">χαρὰν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">π</span>. «dar-nos alegria» 1 Cl 63:2. <span class=\"greek\">ἐργασίαν</span> <span class=\"greek\">πολλήν</span> «proporcionar grande lucro» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:16</a> (Jos., Ant. 15, 332 <span class=\"greek\">πλείστην</span> <span class=\"greek\">ἐργασίαν</span> <span class=\"greek\">παρασχόν</span>).—Sem dativo (veja referência a Hdt. acima.—Sir 29:4, variante textual) Hm 11:20. <span class=\"greek\">ξενισμόν</span> «causar admiração» IEph 19:2. <span class=\"greek\">ἐκζητήσεις</span> «suscitar especulações» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:4</a>.<br><br>ⓑ Médio (B-D-F §316, 3; Rob. 810): conceder <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> «algo a alguém» (Diod S 20, 62, 1 <span class=\"greek\">παρείχετο</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐμπόροις</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀσφάλειαν</span>; Jos., Ant. 9, 255; cf. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">δίκαια</span> <span class=\"greek\">παρέσχοντο</span> = «apresentaram suas reivindicações»: carta de MAurelius ln. 33 em ZPE 8, ’71, 170f) <span class=\"greek\">τοῖς</span> <span class=\"greek\">τεχνίταις</span> <span class=\"greek\">ἐργασίαν</span> «trabalho aos artesãos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:24</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">δίκαιον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰσότητα</span> «o que é justo e equitativo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:1</a>. <span class=\"greek\">ἄξιός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">παρέξῃ</span> <span class=\"greek\">τοῦτο</span> «é digno de que lhe concedas isso» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:4</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῦτος</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">πένητι</span> Hs 2, 7. <span class=\"greek\">πλέον</span> «mais» IRo 2:2. <span class=\"greek\">παρέξομαι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κλητοῖς</span> <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐκλέκτοις</span> <span class=\"greek\">μου</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">αἰτήσωνταί</span> <span class=\"greek\">με</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κολάσεως</span> «concederei aos meus chamados e eleitos que me solicitarem a libertação do tormento do pecador que escolherem» ApcPt Rainer (conforme emenda de James; cf. SibOr 2, 330–33). Oferecer 1 Cl 20:10.—Larfeld I 501f. M-M.</p></section></article>"};
